236	function updateStatusTable(tableBody, statusMap, isStable, onBranchCellClick) {
237	    for (const [repoId, statusInfo] of Object.entries(statusMap)) {
238	        const row = tableBody.querySelector(`tr[data-repo-id="${CSS.escape(repoId)}"]`);
239	        if (!row) continue;
240	        updateRepoStatusCells(row, repoId, statusInfo, isStable, onBranchCellClick);
241	    }
242	}
